// Java Program demonstrating basic OOP encapsulation, control flow, and arrays
public class Student Grade Demo {
    private String student Name;
    private int[] marks;

public Student Grade Demo(String name, int[] marks) {
        this.student Name = name;
        this.marks = marks;
    }

public double calculate Average() {
        int sum = 0;
        for (int mark : marks) {
            sum += mark;
        }
        return (double) sum / marks.length;
    }

public void display Report() {
        double avg = calculate Average();
        char grade = (avg >= 90) ? 'A' : (avg >= 75) ? 'B' : (avg >= 50) ? 'C' : 'F';
        System.out.println("Student: " + student Name + " | Average: " + avg + " | Grade: " + grade);
    }

public static void main(String[] args) {
        int[] scores = {85, 92, 78, 88, 95};
        Student Grade Demo s = new Student Grade Demo("Sita", scores);
        s.display Report();
    }
}
```
Output:
Student: Sita | Average: 87.6 | Grade: B

