interface Printable {
    void print Details();
}

class Employee implements Printable {
    protected int emp Id;
    protected String name;

public Employee(int emp Id, String name) {
        this.emp Id = emp Id;
        this.name = name;
    }

public double calculate Salary() {
        return 30000.0;
    }

@Override
    public void print Details() {
        System.out.println("Employee ID: " + emp Id + ", Name: " + name);
    }
}

public Manager(int emp Id, String name, double bonus) {
        super(emp Id, name); // Call superclass constructor
        this.bonus = bonus;
    }

@Override
    public double calculate Salary() {
        return super.calculate Salary() + bonus; // Method Overriding
    }

@Override
    public void print Details() {
        super.print Details();
        System.out.println("Role: Manager | Total Salary: " + calculate Salary());
    }
}

public class Inheritance Demo {
    public static void main(String[] args) {
        Employee emp = new Manager(101, "Ravi Kumar", 25000.0); // Dynamic dispatch
        emp.print Details();
    }
}
```
