// Java Program demonstrating Custom Exception and Multithreading with Runnable
class Insufficient Funds Exception extends Exception {
    public Insufficient Funds Exception(String msg) {
        super(msg);
    }
}

public synchronized void withdraw(double amount) throws Insufficient Funds Exception {
        if (amount > balance) {
            throw new Insufficient Funds Exception("Withdrawal of " + amount + " failed! Balance is " + balance);
        }
        balance -= amount;
        System.out.println(Thread.current Thread().get Name() + " withdrew " + amount + ". Remaining: " + balance);
    }
}

public class Thread Exception Demo {
    public static void main(String[] args) {
        Bank Account account = new Bank Account();

Runnable task = () -> {
            try {
                account.withdraw(3000.0);
            } catch (Insufficient Funds Exception e) {
                System.err.println(Thread.current Thread().get Name() + " caught: " + e.get Message());
            }
        };

Thread t 1 = new Thread(task, "ATM-1");
        Thread t 2 = new Thread(task, "ATM-2");
        t 1. start();
        t 2. start();
    }
}
